# include <iostream>
using namespace std;
int n, x, y, z, sz[10][10], dp[10][10][10][10];
int main (){
    cin >> n;
    for (int i = 1; ; i++){
        cin >> x >> y >> z;
        if (x == 0 && y == 0 && z == 0){
            break;
        }else{
            sz[x][y] = z;
        }
    }
    for (int i = 1; i <= n; i++){
        for (int j = 1; j <= n; j++){
            for (int k = 1; k <= n; k++){
                for (int l = 1; l <= n; l++){
                    dp[i][j][k][l] = max(max(dp[i - 1][j][k - 1][l], dp[i - 1][j][k][l - 1]), max(dp[i][j - 1][k][l - 1], dp[i][j - 1][k - 1][l])) + sz[i][j];
                    if (i != k && j != l){
                        dp[i][j][k][l] += sz[k][l];
                    }
                }
            }
        }
    }
    cout << dp[n][n][n][n];
    return 0;
}

