int n, x, y, z, a[10][10], f[10][10][10][10];
int main(){
    cin >> n;
    while (cin >> x >> y >> z) a[x][y]=z;
    for(int i=1; i<=n; i++)
        for(int j=1; j<=n; j++)
            for(int k=1; k<=n; k++)
