                    f[i][j][k][l]=max({f[i-1][j][k-1][l], f[i][j-1][k-1][l], f[i-1][j][k][l-1], f[i][j-1][k][l-1]})+a[i][j]+(i!=k||j!=l)*a[k][l];
    cout << f[n][n][n][n];
